string caesar(const string& text, int shift) {
    string out;
    for (char ch : text) {
        if (ch >= 'a' && ch <= 'z')
            out += char((ch - 'a' + shift + 26) % 26 + 'a');
        else if (ch >= 'A' && ch <= 'Z')
            out += char((ch - 'A' + shift + 26) % 26 + 'A');
        else
            out += ch;
    }
    return out;
}

int main() {
    string msg = "Attack at dawn!";
    int shift = 3; // tweak
    cout << "Plain : " << msg << endl;
    cout << "Secret: " << caesar(msg, shift) << endl;
    cout << "Back  : " << caesar(caesar(msg, shift), -shift) << endl;
    return 0;
}

