bool is_palindrome(string s) {
    string clean;
    for (char ch : s) {
        if (isalnum((unsigned char)ch))
            clean += (char)tolower((unsigned char)ch);
    }
    int i = 0, j = (int)clean.size() - 1;
    while (i < j) {
        if (clean[i] != clean[j]) return false;
        i++; j--;
    }
    return true;
}

int main() {
    string tests[] = {"Level", "CodeItAll", "A man a plan a canal Panama", "12321"};
    for (auto& t : tests) {
        cout << "\"" << t << "\" → " << (is_palindrome(t) ? "YES" : "no") << endl;
    }
    return 0;
}

