    Job jobs[] = {{12, '+', 5}, {10, '/', 4}, {3, '*', 7}, {9, '-', 2}};
    for (auto j : jobs) {
        cout << j.a << " " << j.op << " " << j.b << " = " << eval(j.a, j.op, j.b) << endl;
    }
    return 0;
}

