string grade(const string& pw) {
    int score = 0;
    bool digit = false, upper = false, lower = false, symbol = false;
    if ((int)pw.size() >= 8) score++;
    if ((int)pw.size() >= 12) score++;
    for (char ch : pw) {
        if (isdigit((unsigned char)ch)) digit = true;
        else if (isupper((unsigned char)ch)) upper = true;
        else if (islower((unsigned char)ch)) lower = true;
        else symbol = true;
    }
    score += digit + upper + lower + symbol;
    if (score <= 2) return "Weak";
    if (score <= 4) return "OK";
    return "Strong";
}

int main() {
    string tests[] = {"abc", "hunter2", "Hunter2!", "C0deItAll#2026"};
    for (auto& t : tests) cout << t << " → " << grade(t) << endl;
    return 0;
}

