#include <iostream>
using namespace std;

char b[3][3] = {{' ',' ',' '},{' ',' ',' '},{' ',' ',' '}};

void show() {
    for (int r = 0; r < 3; r++) {
        cout << " " << b[r][0] << " | " << b[r][1] << " | " << b[r][2] << endl;
        if (r < 2) cout << "---+---+---" << endl;
    }
    cout << endl;
}

char winner() {
    for (int i = 0; i < 3; i++) {
        if (b[i][0] != ' ' && b[i][0] == b[i][1] && b[i][1] == b[i][2]) return b[i][0];
        if (b[0][i] != ' ' && b[0][i] == b[1][i] && b[1][i] == b[2][i]) return b[0][i];
    }
    if (b[0][0] != ' ' && b[0][0] == b[1][1] && b[1][1] == b[2][2]) return b[0][0];
    if (b[0][2] != ' ' && b[0][2] == b[1][1] && b[1][1] == b[2][0]) return b[0][2];
    return ' ';
}

int main() {
    int moves[][2] = {{1,1},{0,0},{0,2},{2,0},{2,2}}; // X,O alternating starting X center
    char turn = 'X';
    for (auto& m : moves) {
        b[m[0]][m[1]] = turn;
        show();
        char w = winner();
        if (w != ' ') { cout << w << " wins!" << endl; return 0; }
        turn = (turn == 'X') ? 'O' : 'X';
    }
    cout << "No winner yet." << endl;
    return 0;
}

#include <iostream>
#include <stack>
#include <string>
using namespace std;

bool valid(const string& s) {
    stack<char> st;
    for (char ch : s) {
        if (ch == '(' || ch == '[' || ch == '{') st.push(ch);
        else if (ch == ')' || ch == ']' || ch == '}') {
            if (st.empty()) return false;
            char o = st.top(); st.pop();
            if ((ch == ')' && o != '(') || (ch == ']' && o != '[') || (ch == '}' && o != '{'))
                return false;
        }
    }
    return st.empty();
}

int main() {
    string tests[] = {"()[]{}", "([)]", "{[]}", "(", "a+(b*c)-{d/e}"};
    for (auto& t : tests)
        cout << t << " → " << (valid(t) ? "OK" : "bad") << endl;
    return 0;
}

