int main() {
    int chest[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int n = 10;
    int target = 23; // tweak
    int lo = 0, hi = n - 1, probes = 0, found = -1;
    while (lo <= hi) {
        probes++;
        int mid = lo + (hi - lo) / 2;
        if (chest[mid] == target) { found = mid; break; }
        if (chest[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    if (found >= 0) cout << "Found " << target << " at index " << found;
    else cout << "Missing " << target;
    cout << " after " << probes << " probes" << endl;
    return 0;
}

