            for (int dr = -1; dr <= 1; dr++) for (int dc = -1; dc <= 1; dc++) {
                if (!dr && !dc) continue;
                int rr = r + dr, cc = c + dc;
                if (rr>=0 && rr<R && cc>=0 && cc<C) n += g[rr][cc];
            }
            next[r][c] = (g[r][c] ? (n == 2 || n == 3) : (n == 3));
        }
        g.swap(next);
        show(gen);
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int eval_expr(const string& s) {
    int i = 0;
    auto num = [&]() {
        int v = s[i] - '0';
        i++;
        return v;
    };
    int value = num();
    while (i < (int)s.size()) {
        char op = s[i++];
        int rhs = num();
        if (op == '+') value += rhs;
        else if (op == '-') value -= rhs;
    }
    return value;
}

int main() {
    string tests[] = {"3+4", "9-2+1", "8-3-2"};
    for (auto& t : tests) cout << t << " = " << eval_expr(t) << endl;
    return 0;
}

